<script setup lang="ts">
import { z } from 'zod'
import { CheckCircle2, EyeOff, KeyRound, LockKeyhole, RefreshCw, ServerCog, ShieldCheck, TriangleAlert } from '~/utils/icons'
import { integrationsStatusSchema, readinessResponseSchema } from '~~/shared/schemas/security'

const connectionSchema = z.object({
  status: z.enum(['mock', 'ready', 'missing', 'unavailable', 'model_missing']),
  latencyMs: z.number().nonnegative(),
  checkedAt: z.string(),
  message: z.string(),
})
const ui=useUiStore();const message=ref('');const messageTone=ref<'success'|'error'>('success');const testing=ref(false)
const {data,status,error,refresh}=await useAsyncData('integration-settings',()=>validatedFetch('/settings/integrations',integrationsStatusSchema))
const {data:readiness,error:readinessError,refresh:refreshReadiness}=await useAsyncData('deployment-readiness',()=>validatedFetch('/readiness',readinessResponseSchema))
function notify(text:string,tone:'success'|'error'='success'){messageTone.value=tone;message.value=text;setTimeout(()=>message.value='',3200)}
async function reloadConfig(){await Promise.all([refresh(),refreshReadiness()]);notify('服务端配置和上线就绪状态已刷新')}
async function test(){
  testing.value=true
  try {
    const result=await validatedFetch('/settings/connection',connectionSchema,{method:'POST'})
    notify(`${result.message}${result.latencyMs ? `（${result.latencyMs} ms）` : ''}`,result.status==='ready'?'success':'error')
  } catch {
    notify('服务端连接检查失败，请查看安全审计日志。','error')
  } finally { testing.value=false }
}
function jumpTo(id:string){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
</script>
<template>
  <div class="settings-page">
    <PageHeader eyebrow="Platform Control" title="平台设置" description="运行模式、服务端集成与访问策略">
      <button class="page-button primary" :disabled="status==='pending'" @click="reloadConfig"><RefreshCw :size="13" :class="{spin:status==='pending'}"/>刷新配置</button>
    </PageHeader>
    <div v-if="message" :class="['success-message',messageTone]" role="status"><CheckCircle2 :size="14"/>{{message}}</div>
    <section class="settings-layout">
      <aside class="settings-nav surface-panel" aria-label="设置目录"><button @click="jumpTo('agent-integration')">Agent 集成</button><button @click="jumpTo('deployment-readiness')">上线就绪检查</button><button @click="jumpTo('security-boundary')">调用安全边界</button><button @click="jumpTo('appearance-settings')">界面主题</button></aside>
      <div class="settings-main">
        <LoadingState v-if="status==='pending'" :rows="6"/><ErrorState v-else-if="error||readinessError" @retry="reloadConfig"/>
        <template v-else-if="data">
          <section id="agent-integration" class="integration-panel surface-panel"><div class="integration-head"><span><ServerCog :size="18"/></span><div><p>规则演进与告警研判 Agent</p><h2>{{data.deepseek.displayModel}}</h2><small>前端不直接连接外部模型服务</small></div><StatusIndicator :status="data.configured||data.useMockApi?'healthy':'degraded'" :label="data.useMockApi?'Mock 模式':data.configured?'已配置':'待配置'"/></div>
            <div v-if="data.useMockApi" class="mode-notice"><TriangleAlert :size="14"/><div><b>当前使用固定 Mock 响应</b><p>Agent 运行、RAG 证据与规则生成均来自静态可复现数据；切换真实模式前请在服务端设置环境变量。</p></div></div>
            <div v-if="!data.useMockApi&&!data.deepseek.configured" class="mode-notice"><TriangleAlert :size="14"/><div><b>DeepSeek 尚未配置</b><p>请在项目根目录 <code>.env</code> 中设置 <code>NUXT_DEEPSEEK_API_BASE</code>、<code>NUXT_DEEPSEEK_API_KEY</code>、<code>NUXT_DEEPSEEK_MODEL</code> 三项；配置后需重启 Nuxt 服务器才会生效。</p></div></div>
            <div class="config-fields"><label><span>API Base</span><div><ServerCog :size="13"/><input :value="data.apiBaseState==='configured'?(data.deepseek.baseUrlHost||'已配置'):data.apiBaseState==='invalid'?'地址格式无效':'未配置'" readonly></div><small><code>NUXT_DEEPSEEK_API_BASE</code> · 此处仅显示域名，原值不返回浏览器</small></label><label><span>API Model ID</span><div><LockKeyhole :size="13"/><input :value="data.deepseek.model||'未配置'" readonly></div><small><code>NUXT_DEEPSEEK_MODEL</code> · 真实模型 ID 由服务端返回</small></label><label><span>API Key</span><div><KeyRound :size="13"/><input :value="data.apiKeyState==='configured'?'••••••••••••••••••••••••':'未配置'" readonly><EyeOff v-if="data.apiKeyState==='configured'" :size="13"/></div><small><code>NUXT_DEEPSEEK_API_KEY</code> · {{data.apiKeyState==='configured'?'已配置':'未配置'}} · 永不返回浏览器</small></label><label><span>前端显示名称</span><div><ShieldCheck :size="13"/><input :value="data.deepseek.displayModel" readonly></div><small>由模型 ID 推导；未配置模型时显示默认名称</small></label></div>
            <div class="integration-actions"><button :disabled="testing" @click="test"><RefreshCw :size="13" :class="{spin:testing}"/>{{testing?'检测中…':'测试连接'}}</button><span><ShieldCheck :size="12"/>真实探测 · 8 秒超时 · 认证信息脱敏</span></div>
          </section>
          <section v-if="readiness" id="deployment-readiness" class="readiness-panel surface-panel"><div class="panel-head readiness-head"><div><h2>上线就绪检查</h2><p>只报告可验证状态，不把开发模式判定为生产可用</p></div><span :class="readiness.status"><ShieldCheck v-if="readiness.status==='ready'" :size="13"/><TriangleAlert v-else :size="13"/>{{readiness.status==='ready'?'已就绪':`${readiness.blockers} 个阻断 · ${readiness.warnings} 个提醒`}}</span></div><div class="readiness-list"><div v-for="check in readiness.checks" :key="check.id" :class="check.status"><span><CheckCircle2 v-if="check.status==='pass'" :size="14"/><TriangleAlert v-else :size="14"/></span><div><b>{{check.label}}</b><p>{{check.detail}}</p></div><em>{{check.status==='pass'?'通过':check.status==='block'?'阻断':'提醒'}}</em></div></div><footer>环境 <code>{{readiness.environment}}</code><span>检查时间 {{new Date(readiness.checkedAt).toLocaleString('zh-CN')}}</span></footer></section>
          <section id="security-boundary" class="security-boundary surface-panel"><div class="panel-head"><div><h2>调用安全边界</h2><p>所有 Agent 请求必须遵守</p></div></div><div class="boundary-flow"><div><b>浏览器</b><span>结构化画像 + 告警 ID</span></div><i>→</i><div><b>Nuxt Server API</b><span>Zod 校验 · 服务端画像核验 · RAG 白名单</span></div><i>→</i><div><b>{{data.displayName}}</b><span>私有凭据 · 结构化响应</span></div></div><ul><li><CheckCircle2 :size="12"/>API Key、API Base 与真实 Model ID 仅存在于服务端 Runtime Config</li><li><CheckCircle2 :size="12"/>Agent 运行固定经过 <code>/api/agent/analyze</code></li><li><CheckCircle2 :size="12"/>客户端画像必须与服务端告警上下文完全一致</li><li><CheckCircle2 :size="12"/>错误响应不包含上游认证头或完整响应体</li><li><CheckCircle2 :size="12"/>仅无 Prompt Injection 风险的授权证据进入上下文</li><li><CheckCircle2 :size="12"/>Agent 无权确认或部署规则</li></ul></section>
          <section id="appearance-settings" class="appearance-panel surface-panel"><div class="panel-head"><div><h2>界面主题</h2><p>选择即时生效并保存在当前设备</p></div></div><div><button v-for="theme in (['dark','light','system'] as const)" :key="theme" :class="{active:ui.themeMode===theme}" :aria-pressed="ui.themeMode===theme" @click="ui.setTheme(theme)"><span>{{theme==='dark'?'深色':theme==='light'?'浅色':'跟随系统'}}</span><small>{{theme==='dark'?'低干扰运营环境':theme==='light'?'明亮办公环境':'自动匹配操作系统'}}</small></button></div></section>
        </template>
      </div>
    </section>
  </div>
</template>
<style scoped>
.settings-page{padding:20px 22px 28px}.page-button{display:flex;align-items:center;gap:5px;height:34px;padding:0 9px;border:1px solid var(--border-default);border-radius:8px;background:var(--surface-1);color:var(--text-secondary);font-size:13px;cursor:pointer}.page-button.primary{border-color:color-mix(in srgb,var(--accent) 50%,var(--border-default));background:var(--accent-muted);color:var(--accent-strong)}.page-button:disabled{opacity:.55;cursor:wait}.success-message{display:flex;align-items:center;gap:5px;margin-bottom:10px;padding:8px 10px;border:1px solid color-mix(in srgb,var(--status-success) 35%,var(--border-default));border-radius:7px;color:var(--status-success);font-size:13px}.success-message.error{border-color:color-mix(in srgb,var(--status-error) 35%,var(--border-default));color:var(--status-error)}.settings-layout{display:grid;grid-template-columns:180px minmax(0,1fr);gap:12px}.settings-nav{position:sticky;top:64px;align-self:start;display:grid;padding:6px}.settings-nav button{height:34px;padding:0 8px;border:0;border-radius:6px;background:transparent;color:var(--text-tertiary);font-size:13px;text-align:left;cursor:pointer}.settings-nav button:hover,.settings-nav button:focus-visible{background:var(--surface-2);color:var(--text-primary)}.settings-main{display:grid;gap:12px}.integration-panel,.security-boundary,.appearance-panel{overflow:hidden;scroll-margin-top:64px}.integration-head{display:flex;align-items:center;gap:9px;min-height:64px;padding:9px 12px;border-bottom:1px solid var(--border-subtle)}.integration-head>span{display:grid;width:34px;height:34px;place-items:center;border-radius:8px;background:var(--accent-muted);color:var(--accent-strong)}.integration-head>div{flex:1}.integration-head p,.integration-head h2,.integration-head small{display:block;margin:0}.integration-head p{color:var(--text-tertiary);font-size:12px}.integration-head h2{font-size:13px}.integration-head small{margin-top:2px;color:var(--text-tertiary);font-size:12px}.mode-notice{display:flex;gap:8px;margin:11px 12px;padding:9px 10px;border-left:2px solid var(--status-warning);background:color-mix(in srgb,var(--status-warning) 7%,transparent);color:var(--status-warning)}.mode-notice b,.mode-notice p{margin:0}.mode-notice b{color:var(--text-primary);font-size:13px}.mode-notice p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.config-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:2px 12px 12px}.config-fields label>span{display:block;margin-bottom:4px;color:var(--text-tertiary);font-size:12px}.config-fields label>div{display:flex;align-items:center;gap:6px;height:32px;padding:0 8px;border:1px solid var(--border-default);border-radius:6px;background:var(--surface-2);color:var(--text-tertiary)}.config-fields input{flex:1;min-width:0;border:0;background:transparent;color:var(--text-secondary);font:12px ui-monospace,monospace}.config-fields small{display:block;margin-top:3px;color:var(--text-tertiary);font-size:12px}.config-fields code{font-size:12px}.integration-actions{display:flex;justify-content:space-between;align-items:center;min-height:42px;padding:0 12px;border-top:1px solid var(--border-subtle);background:var(--surface-2)}.integration-actions button{display:flex;align-items:center;gap:4px;height:28px;padding:0 7px;border:1px solid var(--border-default);border-radius:5px;background:var(--surface-1);color:var(--text-secondary);font-size:12px;cursor:pointer}.integration-actions span{display:flex;align-items:center;gap:4px;color:var(--status-success);font-size:12px}.spin{animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.panel-head{min-height:47px;padding:8px 12px;border-bottom:1px solid var(--border-subtle)}.panel-head h2,.panel-head p{margin:0}.panel-head h2{font-size:14px}.panel-head p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.boundary-flow{display:grid;grid-template-columns:1fr 26px 1.2fr 26px 1fr;align-items:center;padding:12px}.boundary-flow>div{padding:8px;border-left:2px solid var(--accent);background:var(--surface-2)}.boundary-flow b,.boundary-flow span{display:block}.boundary-flow b{font-size:13px}.boundary-flow span{margin-top:2px;color:var(--text-tertiary);font-size:12px}.boundary-flow>i{color:var(--border-strong);font-style:normal;text-align:center}.security-boundary ul{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:0;padding:10px 12px;border-top:1px solid var(--border-subtle);list-style:none}.security-boundary li{display:flex;align-items:center;gap:5px;color:var(--text-secondary);font-size:12px}.security-boundary li svg{color:var(--status-success)}.security-boundary code{font-size:12px}.appearance-panel>div:last-child{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;padding:10px 12px}.appearance-panel button{padding:8px;border:1px solid var(--border-default);border-radius:7px;background:var(--surface-2);color:var(--text-secondary);cursor:pointer;text-align:left}.appearance-panel button:hover{border-color:var(--border-strong)}.appearance-panel button.active{border-color:var(--accent);background:var(--accent-muted)}.appearance-panel button span,.appearance-panel button small{display:block}.appearance-panel button span{font-size:13px}.appearance-panel button small{margin-top:2px;color:var(--text-tertiary);font-size:12px}
@media(max-width:800px){.settings-layout{grid-template-columns:1fr}.settings-nav{display:flex;overflow-x:auto}.settings-nav button{white-space:nowrap}.config-fields{grid-template-columns:1fr}}@media(max-width:600px){.settings-page{padding:16px 12px 24px}.security-boundary ul{grid-template-columns:1fr}.boundary-flow{grid-template-columns:1fr}.boundary-flow>i{transform:rotate(90deg)}.appearance-panel>div:last-child{grid-template-columns:1fr}}
</style>
<style scoped>
.readiness-panel{overflow:hidden;scroll-margin-top:64px}.readiness-head{display:flex;justify-content:space-between;align-items:center}.readiness-head>span{display:flex;align-items:center;gap:5px;padding:3px 7px;border-radius:5px;background:color-mix(in srgb,var(--status-warning) 9%,transparent);color:var(--status-warning);font-size:12px}.readiness-head>span.ready{background:color-mix(in srgb,var(--status-success) 9%,transparent);color:var(--status-success)}.readiness-list{display:grid;grid-template-columns:1fr 1fr}.readiness-list>div{display:grid;grid-template-columns:22px 1fr auto;gap:6px;align-items:start;min-height:58px;padding:9px 10px;border-right:1px solid var(--border-subtle);border-bottom:1px solid var(--border-subtle)}.readiness-list>div:nth-child(even){border-right:0}.readiness-list>div>span{color:var(--status-success)}.readiness-list>div.warn>span{color:var(--status-warning)}.readiness-list>div.block>span{color:var(--status-error)}.readiness-list b,.readiness-list p{margin:0}.readiness-list b{font-size:12px}.readiness-list p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.readiness-list em{color:var(--status-success);font-size:12px;font-style:normal}.readiness-list .warn em{color:var(--status-warning)}.readiness-list .block em{color:var(--status-error)}.readiness-panel footer{display:flex;justify-content:space-between;padding:8px 10px;background:var(--surface-2);color:var(--text-tertiary);font-size:12px}.readiness-panel footer code{color:var(--text-secondary)}
@media(max-width:700px){.readiness-list{grid-template-columns:1fr}.readiness-list>div{border-right:0}.readiness-head{align-items:flex-start;gap:8px}.readiness-panel footer{display:grid;gap:3px}}
</style>
